for feature in ("F01", "F02"):
    path = HANDOFF / f"S2-D2-{feature}.md"
    content = path.read_text(encoding="utf-8")
    lines = content.splitlines()
    seen = set()
    for index, line in enumerate(lines):
        match = re.match(r"^\|\s*(F0[12]-TC-\d{3})\s*\|", line)
        if not match or not match.group(1).startswith(feature):
            continue
        case = match.group(1)
        if case in seen or case not in UPDATES:
            continue
        seen.add(case)
        cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
        status, evidence, gap = UPDATES[case]
        # These historical ledger labels added evidence classes absent from the
        # approved RTT. The RTT's own evidence column remains authoritative.
        if case == "F01-TC-001":
            cells[2] = "M"
        elif case == "F01-TC-046":
            cells[2] = "H"
        cells[3] = status
        if feature == "F01":
            cells[4], cells[5] = evidence, gap
        else:
            cells[4] = f"{evidence} {'Closure' if status == 'PASS' else 'Remaining'}: {gap}"
        lines[index] = "| " + " | ".join(cells) + " |"
    expected = {case for case in UPDATES if case.startswith(feature)}
    if seen != expected:
        raise ValueError(f"Missing {feature} rows: {sorted(expected - seen)}")
    statuses = [line.strip().strip("|").split("|")[3].strip() for line in lines if re.match(rf"^\|\s*{feature}-TC-\d{{3}}\s*\|", line)]
    if len(statuses) != (46 if feature == "F01" else 45):
        raise ValueError(f"Unexpected {feature} case count: {len(statuses)}")
    counts = {name: statuses.count(name) for name in ("PASS", "FAIL", "PARTIAL", "BLOCKED", "NOT RUN")}
    totals = ", ".join(f"{counts[name]} {name}" for name in ("PASS", "FAIL", "PARTIAL", "BLOCKED", "NOT RUN"))
    content = "\n".join(lines) + "\n"
    if feature == "F01":
        final_total = f"**Integrated totals (2026-10-17):** {totals}. PASS rows have complete independent row evidence; each PARTIAL row retains unverified assertions. Production-wired F01/F02 integration and synthetic browser journeys ran. Earlier F01-only and initial integrated checkpoints are preserved in the historical narrative above."
        content = content.replace(
            "**Totals:** 1 PASS, 0 FAIL, 32 PARTIAL, 13 BLOCKED, 0 NOT RUN. Each PARTIAL row retains unverified assertions; no I-class test ran.",
            final_total,
        )
        content = re.sub(r"\*\*Integrated totals \(2026-10-17\):\*\*[^\n]*", final_total, content, count=1)
    else:
        marker = "### Implementation checkpoint and verification record"
        note = f"**Integrated RTT totals (2026-10-17):** {totals}. PASS rows have complete independent row evidence; the nine previously NOT RUN rows now have partial local evidence. Every PARTIAL row retains missing approved assertions or evidence classes. See the consolidated 91-case matrix and final report in `verification-evidence/`.\n\n"
        content = re.sub(r"\*\*Integrated RTT totals \(2026-10-17\):\*\*[^\n]*\n\n", "", content, count=1)
        if note not in content:
            content = content.replace(marker, note + marker, 1)
    path.write_text(content, encoding="utf-8")
    print(f"Reconciled {feature}: {len(seen)} updated rows")
